import type {
  IsoTimestamp,
  MemberId,
  OrgId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
  InvitationId,
} from "./common";

/**
 * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`
 * below is the single source of truth for "at least this role" comparisons —
 * never compare role strings directly.
 */
export type Role = "owner" | "admin" | "member" | "viewer";

export const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

export const ROLE_RANK: Readonly<Record<Role, number>> = {
  owner: 4,
  admin: 3,
  member: 2,
  viewer: 1,
};

export type MemberStatus = "active" | "invited" | "suspended";

export interface User extends Timestamps {
  readonly id: UserId;
  readonly email: string;
  readonly name: string;
  readonly avatarUrl: string | null;
  readonly timezone: string;
  readonly emailVerifiedAt: IsoTimestamp | null;
}

export interface Member extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: MemberId;
  readonly userId: UserId;
  readonly role: Role;
  readonly status: MemberStatus;
  readonly invitedBy: UserId | null;
  readonly joinedAt: IsoTimestamp | null;
  readonly lastSeenAt: IsoTimestamp | null;
}

/** A member joined with the user record it points at, for list UIs. */
export interface MemberWithUser extends Member {
  readonly user: User;
}

export interface Invitation extends Timestamps, TenantScoped {
  readonly id: InvitationId;
  readonly email: string;
  readonly role: Role;
  readonly invitedBy: UserId;
  readonly token: string;
  readonly expiresAt: IsoTimestamp;
  readonly acceptedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
}

/**
 * The authenticated principal for one request, always resolved for exactly one
 * organization. Everything that authorizes a mutation takes an `Actor` — see
 * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in
 * `src/lib/tenant.ts`.
 */
export interface Actor {
  readonly userId: UserId;
  readonly orgId: OrgId;
  readonly role: Role;
  /** Staff impersonation / internal tooling escape hatch. Defaults to false. */
  readonly isPlatformStaff?: boolean;
}

export interface SessionPrincipal {
  readonly userId: UserId;
  readonly email: string;
  readonly activeOrgId: OrgId | null;
  readonly expiresAt: IsoTimestamp;
}

/** True when `role` is at least as privileged as `atLeast`. */
export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
}
---
/**
 * ULID generation and validation. Every branded id in the app is produced
 * here, so ids sort lexicographically by creation time and the repositories
 * can use them as pagination cursors without a separate sort column.
 */
/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

function encodeTime(time: number): string {
  let remaining = time;
  let out = "";
  for (let i = 0; i < TIME_LENGTH; i += 1) {
    const mod = remaining % 32;
    out = ALPHABET[mod] + out;
    remaining = (remaining - mod) / 32;
  }
  return out;
}

function encodeRandom(next: () => number): string {
  let out = "";
  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    out += ALPHABET[next() % 32];
  }
  return out;
}

/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same
 *  implementation runs on the server, in the browser and on the edge. */
export function newId(): string {
  const bytes = new Uint8Array(RANDOM_LENGTH);
  globalThis.crypto.getRandomValues(bytes);
  let cursor = 0;
  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);
}

export function isUlid(value: string): boolean {
  return ULID_PATTERN.test(value);
}

/**
 * A deterministic id generator for tests and the seed script: same seed,
 * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so
 * fixtures are byte-stable across runs.
 */
export function idFactory(seed: number): () => string {
  let state = (seed | 0) || 0x2545_f491;
  let counter = 0;

  const next = (): number => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return Math.abs(state);
  };

  return () => {
    counter += 1;
    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.
    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);
  };
}
