/**
 * Ownership handover offers. At most one row per org is ever `pending` at a
 * time — the service layer enforces that, not a unique index, since a
 * resolved offer must stay in the table for history.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const EXPIRY_DAYS = 7;

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + EXPIRY_DAYS * MS_PER_DAY),
  );

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: OwnershipHandoverStatus,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: resolvedAt })
    .where(
      and(orgPredicate(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, id)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${id} not found in org ${orgId}`);
  return toOwnershipHandover(row);
}

