/**
 * Holding the owner role is not enough to offer or withdraw a handover — it
 * must be the specific member the org record points at as `ownerId`.
 */
function assertIsRecordedOwner(actor: Actor, org: Organization): void {
  assertCan(actor, "org:transfer_ownership", orgResource(org.id));

  if (actor.userId !== org.ownerId) {
    throw new PermissionDeniedError("org:transfer_ownership", {
      action: "org:transfer_ownership",
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

function isLapsed(handover: OwnershipHandover, now: Date = new Date()): boolean {
  return now.getTime() >= new Date(handover.expiresAt).getTime();
}

/**
 * The open offer for `orgId`, or `null` — lazily expiring a stale `pending`
 * row in passing so nothing downstream ever treats a lapsed offer as open.
 */
async function loadOpenHandover(orgId: OrgId): Promise<OwnershipHandover | null> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending) return null;

  if (isLapsed(pending)) {
    await handoverRepo.resolveHandover(
      orgId,
      pending.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
    return null;
  }

  return pending;
}

/**
 * The recorded owner offers the workspace to another active member. Only one
 * offer may be open per workspace at a time.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertIsRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  if ((await loadOpenHandover(orgId)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await handoverRepo.insertHandover(orgId, actor.userId, toUserId);

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered ownership",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member accepts, whatever role they currently hold. They become
 * the recorded owner and the owner role; the previous owner steps down to
 * admin if they still hold the owner role. Everything published here runs on
 * behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (isLapsed(pending)) {
    await handoverRepo.resolveHandover(
      orgId,
      pending.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
    throw new OwnershipHandoverError("expired");
  }

  const acceptingMember = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (acceptingMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(
      orgId,
      acceptingMember.id,
      "owner",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: acceptingMember.role,
      to: updated.role,
    });
  }

  const previousOwnerMember = await memberRepo.findMember(orgId, pending.fromUserId);
  if (previousOwnerMember && previousOwnerMember.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(
      orgId,
      previousOwnerMember.id,
      "admin",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: previousOwnerMember.role,
      to: demoted.role,
    });
  }

  const updatedOrg = await orgRepo.updateOwner(orgId, actor.userId);

  await handoverRepo.resolveHandover(
    orgId,
    pending.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
  });

  return updatedOrg;
}

/** The offered member declines; nothing is pending afterward. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

