/**
 * If either side of an open ownership handover leaves the workspace, the
 * offer no longer makes sense and is withdrawn automatically.
 */
async function withdrawHandoverInvolving(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending) return;
  if (pending.fromUserId !== userId && pending.toUserId !== userId) return;

  await handoverRepo.resolveHandover(
    orgId,
    pending.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

